import{z as s,x as o,o as A,c as d,q as t,j as i,D as a,d as e,s as r,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"难度分级与课程合成","description":"","frontmatter":{"title":"难度分级与课程合成","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-difficulty-curriculum.md","filePath":"llm/synthetic-difficulty-curriculum.md","lastUpdated":1791413859000}'),u={name:"llm/synthetic-difficulty-curriculum.md"};function c(m,E,p,D,f,h){const B=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="难度分级与课程合成" tabindex="-1">难度分级与课程合成 <a class="header-anchor" href="#难度分级与课程合成" aria-label="Permalink to &quot;难度分级与课程合成&quot;">​</a></h1><div class="epigraph"><p>难度不是题的属性，是题与学生当前关系的一个读数：学生变了，同一道题会从「难」走到「中」再走到「废」。</p><footer>—— 据 Zelikman 等 STaR；Muennighoff 等 s1；DeepSeek-AI R1 的难度过滤整理</footer></div><p><a href="/llm/synthetic-agent-traj">上一课</a>把域合成推进到轨迹与结局判定；本课回到所有域共享的一站：题池进训练前，每道题还欠一个「难度」标签。<a href="/llm/rl-difficulty-curriculum">难度课程</a>与<a href="/llm/synthetic-curriculum-close">合成课程与自出题</a>已在 RL 语境立了「中间通过率才有梯度」的规矩，<a href="/llm/instruction-curriculum">难度分层与课程</a>讲了 SFT 侧的桶与混合比序列。本课把难度当作通用的数据工程原语收拢：标签从哪来、桶怎么分、课程怎么排、标签什么时候会过期。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>难度标签有三个来源，可靠性与成本此消彼长。当前策略的组通过率最可靠：它直接量「这题对现在的学生有没有梯度信号」。教师自评最便宜但校准最差：同一道题对教师容易、对学生未必，教师还倾向于把「步骤多」当成「难」。结构代理（步数、长度、知识点层级）介于两者之间，单用会犯系统性错误——把啰嗦当难、把套话当易。典型工程错误是：用教师自评难度排课程，训练前期学生全在过易题（无信号），后期突然面对全难题（无梯度），课程表形同虚设。<span class="marginnote">常见误区：把「步骤多」当「难」。一道 10 步套模板的题，教师自评很难，学生通过率却有 0.6；一句看似简单的话可能藏着巧构造，通过率只有 0.05。教师度量的是题目外观，学生通过率度量的才是梯度信号——两者经常对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标签、分箱、排序、重标四步。标签：有程序真值的域一律用通过率——组采样 \\(k\\) 条估通过率 \\(r\\)，落在 \\(0.3 \\lt r \\lt 0.7\\) 中间带的题才有组间分差；无真值域退回结构代理加教师自评的加权组合，并注明置信度。分箱：按通过率分箱而不是按绝对题号，箱宽按训练批次的数据量定；两端箱（全对全错）默认降权或搁置而非删除——它们留给能力变化后的重标。排序：课程是各桶混合比随训练移动的序列，静态配比是它的特例；移动的依据是实测通过率的漂移，不是预设时间表。重标：策略每前进一段，抽题重测通过率，过期标签按新读数改写——星级不是永久的。</p>',7)),(A(),i(n,null,{default:a(()=>[r(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E9%A2%98%E6%B1%A0%22%5D%20--%3E%20MEAS%5B%22%E7%BB%84%E9%87%87%E6%A0%B7%E4%BC%B0%E9%80%9A%E8%BF%87%E7%8E%87%22%5D%0A%20%20MEAS%20--%3E%20BIN%5B%22%E6%8C%89%E9%80%9A%E8%BF%87%E7%8E%87%E5%88%86%E7%AE%B1%22%5D%0A%20%20BIN%20--%3E%20CTRL%7B%22%E5%9C%A8%E4%B8%AD%E9%97%B4%E5%B8%A6%200.3-0.7%EF%BC%9F%22%7D%0A%20%20CTRL%20--%3E%7C%E5%85%A8%E5%AF%B9%E5%85%A8%E9%94%99%7C%20PARK%5B%22%E9%99%8D%E6%9D%83%E6%88%96%E6%90%81%E7%BD%AE%E5%BE%85%E9%87%8D%E6%A0%87%22%5D%0A%20%20CTRL%20--%3E%7C%E7%AA%97%E5%86%85%7C%20MIX%5B%22%E5%90%84%E6%A1%B6%E6%B7%B7%E5%90%88%E6%AF%94%E5%BA%8F%E5%88%97%22%5D%0A%20%20MIX%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRAIN%20--%3E%20UPD%5B%22%E7%AD%96%E7%95%A5%E6%9B%B4%E6%96%B0%22%5D%0A%20%20UPD%20--%3E%20RE%5B%22%E6%8A%BD%E9%A2%98%E9%87%8D%E6%B5%8B%EF%BC%9A%E6%A0%87%E7%AD%BE%E9%87%8D%E6%A0%87%22%5D%0A%20%20RE%20--%3E%20BIN%0A%20%20AUD%5B%22%E9%A2%98%E5%9E%8B%E8%A6%86%E7%9B%96%E5%AE%A1%E8%AE%A1%E5%B9%B6%E8%A1%8C%22%5D%20--%3E%20MIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"难度之所以是数据维度而不是训练技巧，是因为它决定梯度密度：组相对或 0-1 损失下，全对全错样本贡献为零，算力花在这些样本上等于空烧；课程的本质是把预算持续搬向边际信息最大的桶。通过率读数把「难」从教师视角换到学生视角，这正是教师自评失准的根源——它度量的对象错了。重标的机制必要性来自读数的移动性：训练改变学生，标签的含义随之漂移，不重标的课程会越来越保守——学生已会的中等题仍占着中间带的预算，新增算力被静默浪费。覆盖审计与难度控制必须并行：把通过率窗收紧时，出题或选题分布会顺着「落在窗内」的压力漂向窄题型——难度达标而题型塌缩，是这门工程最常见的隐形失败，题型网格的占比要单独设阈值。",-1)),(A(),i(n,null,{default:a(()=>[r(B,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20B1%5B%22%E5%85%A8%E5%AF%B9%E6%A1%B6%3A%20%E7%BB%84%E5%86%85%E6%97%A0%E5%88%86%E5%B7%AE%22%5D%20--%3E%20Z%5B%22%E6%A2%AF%E5%BA%A6%E8%B4%A1%E7%8C%AE%E4%B8%BA%E9%9B%B6%2C%20%E7%AE%97%E5%8A%9B%E7%A9%BA%E7%83%A7%22%5D%0A%20%20B2%5B%22%E5%85%A8%E9%94%99%E6%A1%B6%3A%20%E7%BB%84%E5%86%85%E6%97%A0%E5%88%86%E5%B7%AE%22%5D%20--%3E%20Z%0A%20%20B3%5B%22%E4%B8%AD%E9%97%B4%E5%B8%A6%200.3-0.7%3A%20%E6%9C%89%E5%AF%B9%E6%9C%89%E9%94%99%22%5D%20--%3E%20G%5B%22%E6%9C%89%E7%BB%84%E9%97%B4%E5%88%86%E5%B7%AE%2C%20%E6%A2%AF%E5%BA%A6%E5%AF%86%E5%BA%A6%E6%9C%80%E9%AB%98%22%5D%0A%20%20G%20--%3E%20M%5B%22%E8%AF%BE%E7%A8%8B%3A%20%E6%8A%8A%E9%A2%84%E7%AE%97%E6%90%AC%E5%90%91%E8%BE%B9%E9%99%85%E4%BF%A1%E6%81%AF%E6%9C%80%E5%A4%A7%E7%9A%84%E6%A1%B6%22%5D%0A%20%20M%20--%3E%20DR%5B%22%E5%AD%A6%E7%94%9F%E5%8F%98%E5%BC%BA%E5%90%8E%E6%97%A7%E4%B8%AD%E9%97%B4%E9%A2%98%E6%B2%89%E5%85%A5%E5%85%A8%E5%AF%B9%E6%A1%B6%2C%20%E9%9C%80%E9%87%8D%E6%A0%87%E5%8F%B3%E7%A7%BB%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：课程像健身的渐进负荷——天天举轻重量（过易题）不长肌肉，第一次就上极限重量（过难题）只受伤不进步。有效训练都在「勉强能完成」的区间，而且随着变强要不断加重——这就是重标右移。</span></p><p><span class="marginnote">s1 用人工精选的一千题起步，R1 式配方用通过率在线过滤——两端是同一原理：前者靠人事先把题卡在中间带，后者让读数随学生更新。差异在维护成本：人工卡难度是一次性的，读数更新是持续的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>通过率读数需要采样预算：每题 \\(k\\) 条的组采样在题池大时是显著算力，重标频率与预算要一起规划。难度不等于价值：过难的题即便偶尔通过，其信号也常被噪声淹没，中间带的追求是「有分差即可」，不是越难越好。无真值域的难度全靠代理，读数失真时课程会系统性错位，此时宁可静态配比也不要假装有课程。最后，难度分级只回答「梯度在哪」，不回答「覆盖够不够」——题型与能力网格的覆盖是下一课多样性的辖区。<span class="marginnote">数字实例：组采样的预算账——题池 10 万题、每题采 8 条估通过率，就是 80 万条生成，相当于整条 SFT 数据再造一遍。所以重标要省着做：每前进一段抽 5%–10% 的题重测，好过全量重测。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>难度标签三来源：通过率最可靠，结构代理居中，教师自评最不可信。</li><li>中间通过率带是梯度存在带，全对全错降权搁置而非删除。</li><li>课程是桶混合比的移动序列，移动依据是实测漂移不是时间表。</li><li>星级会过期：策略每进一步，抽题重测重标。</li><li>难度窗收紧时题型会塌缩，覆盖审计必须并行。</li><li>出处：Zelikman 等 STaR 2022；Muennighoff 等 s1 2025；DeepSeek-AI R1 2025。</li></ul>',6))])}const T=s(u,[["render",c]]);export{_ as __pageData,T as default};
